def solve(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    colors=[c for c in cnt if c!=bg]
    # bar color: forms contiguous straight segments of len>1; marker color otherwise
    import numpy as np
    a=np.array(g)
    def segs(color):
