        for r in range(h):
            c=0
            while c<w:
                if a[r,c]==color:
                    c0=c
                    while c<w and a[r,c]==color: c+=1
                    if c-c0>1: out.append(('H',r,c0,c-1))
                else: c+=1
        for c in range(w):
            r=0
            while r<h:
                if a[r,c]==color:
                    r0=r
                    while r<h and a[r,c]==color: r+=1
                    if r-r0>1: out.append(('V',c,r0,r-1))
                else: r+=1
        return out
    bar=None; mark=None
    for col in colors:
        s=segs(col)
        if s: bar=col; bars=s
        else: mark=col
    markers=[(r,c) for r in range(h) for c in range(w) if a[r,c]==mark]
    out=[row[:] for row in g]
    def put(r,c,v):
        if 0<=r<h and 0<=c<w: out[r][c]=v
    # assign markers to bars
    assigns={i:[] for i in range(len(bars))}
    for (mr,mc) in markers:
        for i,(o,p0,p1) in enumerate(bars):
            if o=='V' and p0<=mr<=p1: assigns[i].append((mr,mc))
            if o=='H' and p0<=mc<=p1: assigns[(mr,mc)] if False else assigns[i].append((mr,mc))
    filled_offsets={i:set() for i in range(len(bars))}
    for i,(o,p0,p1) in enumerate(bars):
        for (mr,mc) in assigns[i]:
            if o=='V':
                off=mr-p0
                # fill between bar col and marker horizontally
                step=1 if mc>p1 else -1
                for c in range(p1+step, mc, step): put(mr,c,mark)
                put(mr,mc,4)
            else:
                off=mc-p0
                step=1 if mr>p1 else -1
                for r in range(p1+step, mr, step): put(r,mc,mark)
                put(mr,mc,4)
            filled_offsets[i].add(off)
    # other bar: fill same offsets fully to far edge
    for i,(o,p0,p1) in enumerate(bars):
        other=1-i
        for off in filled_offsets[other]:
            if o=='V':
                r=p0+off
                if r>h-1: continue
                step=1 if p1==0 else -1  # bar at left edge -> fill right
                # decide direction: toward far edge
                if p1 < w/2: rng=range(p1+1,w)
                else: rng=range(0,p1)
                for c in rng: put(r,c,mark)
            else:
                c=p0+off
                if c>w-1: continue
                if p1 < h/2: rng=range(p1+1,h)
                else: rng=range(0,p1)
                for r in rng: put(r,c,mark)
    return out

